@@ -0,0 +1,15 @@
+import { createEventCard } from './event-card.js';
+
+export function sortEventCards(events) {
+  return events
+    .map((event) => ({
+      event,
+      card: createEventCard(event),
+      timestamp: new Date(event.startsAt).getTime(),
+    }))
+    .sort((a, b) => a.timestamp - b.timestamp);
+}
+
+export function buildAgenda(events) {
+  return sortEventCards(events).map(({ card }) => card);
+}

